REVOKE ALL ON FUNCTION public.kinra_feature_schemas() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.kinra_feature_schemas() TO authenticated, service_role;

-- Resource descriptions are metadata, never a rendering instruction. The bucket
-- remains private; an authenticated reader needs both a published resource and
-- its still-published parent expert. No Storage object is made public.
ALTER TABLE public.feature_records DROP CONSTRAINT feature_public_kinds;
ALTER TABLE public.feature_records ADD CONSTRAINT feature_public_kinds CHECK(visibility='private' OR kind IN ('expert','expert_resource','facility','review','group','group_member','post','reaction','article','organization','organization_member','membership_plan'));
CREATE UNIQUE INDEX expert_resource_storage_path ON public.feature_records((payload->>'storage_path')) WHERE kind='expert_resource';
CREATE FUNCTION public.kinra_safe_external_url(value text) RETURNS boolean LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT value IS NOT NULL AND value ~* '^https?://[^/@?#[:space:]\\]+([/?#][^[:cntrl:]\\]*)?$' AND value !~ '[[:cntrl:][:space:]\\]'
$$;
CREATE FUNCTION public.kinra_guard_expert_resource() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE parent public.feature_records; link text; field text; facility text;
BEGIN
 IF NEW.kind IN ('expert','facility') THEN
  FOREACH field IN ARRAY ARRAY['website','map_url','tour_url'] LOOP
   IF NEW.payload ? field AND NOT public.kinra_safe_external_url(NEW.payload->>field) THEN RAISE EXCEPTION 'Use an HTTP or HTTPS link without credentials or control characters.' USING ERRCODE='23514'; END IF;
  END LOOP;
  IF NEW.kind='facility' AND NEW.payload ? 'promotion' AND NOT public.kinra_safe_external_url(NEW.payload->'promotion'->>'url') THEN RAISE EXCEPTION 'Use a safe HTTP or HTTPS promotion link.' USING ERRCODE='23514'; END IF;
  IF NEW.kind='expert' AND NEW.payload ? 'facility_ids' THEN
   FOR facility IN SELECT jsonb_array_elements_text(NEW.payload->'facility_ids') LOOP
    IF NOT EXISTS(SELECT 1 FROM public.feature_records f WHERE f.id=facility::uuid AND f.kind='facility' AND public.kinra_feature_visible(f.id)) THEN RAISE EXCEPTION 'Choose an available facility for a self-reported affiliation.' USING ERRCODE='23514'; END IF;
   END LOOP;
  END IF;
 END IF;
 IF NEW.kind<>'expert_resource' THEN RETURN NEW; END IF;
 SELECT * INTO parent FROM public.feature_records WHERE id=(NEW.payload->>'expert_id')::uuid AND kind='expert';
 IF parent.id IS NULL OR parent.owner_id IS DISTINCT FROM NEW.owner_id THEN RAISE EXCEPTION 'Resources must belong to your own expert profile.' USING ERRCODE='42501'; END IF;
 IF TG_OP='UPDATE' AND (NEW.payload->>'expert_id' IS DISTINCT FROM OLD.payload->>'expert_id' OR NEW.payload->>'storage_path' IS DISTINCT FROM OLD.payload->>'storage_path') THEN RAISE EXCEPTION 'A resource file and its expert identity cannot be replaced. Upload a new resource.' USING ERRCODE='23514'; END IF;
 link:=NEW.payload->>'storage_path';
 IF link !~ ('^'||NEW.owner_id::text||'/[0-9a-f-]{36}\.pdf$') OR NEW.payload->>'mime'<>'application/pdf' OR NEW.payload->>'filename' ~ '[[:cntrl:]/\\]' THEN RAISE EXCEPTION 'Choose your uploaded PDF and a safe filename.' USING ERRCODE='23514'; END IF;
 -- Storage metadata supplies the actual MIME and byte count, not client claims.
 IF NOT EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='expert-materials' AND o.name=link AND o.metadata->>'mimetype'='application/pdf' AND (o.metadata->>'size')::bigint=(NEW.payload->>'bytes')::bigint AND (o.metadata->>'size')::bigint BETWEEN 1 AND 10485760) THEN RAISE EXCEPTION 'Upload the selected PDF before saving its resource entry.' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
-- Narrow definer: resolves only the resource's parent and Storage metadata for
-- validation, including private parents; it returns no other account records.
CREATE TRIGGER guard_expert_resource BEFORE INSERT OR UPDATE ON public.feature_records FOR EACH ROW EXECUTE FUNCTION public.kinra_guard_expert_resource();
-- Narrow public-parent boolean avoids recursive feature_records RLS. It never
-- exposes private expert metadata or accepts an arbitrary acting account.
CREATE FUNCTION public.kinra_expert_published(expert_id uuid,resource_owner uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.feature_records p WHERE p.id=expert_id AND p.kind='expert' AND p.owner_id=resource_owner AND p.visibility='public' AND NOT public.kinra_feature_blocked(p.owner_id))
$$;
CREATE POLICY "Expert resource requires published parent" ON public.feature_records AS RESTRICTIVE FOR SELECT TO authenticated USING(
 kind<>'expert_resource' OR owner_id=auth.uid() OR visibility='public' AND public.kinra_expert_published((payload->>'expert_id')::uuid,owner_id)
);
INSERT INTO storage.buckets(id,name,public,file_size_limit,allowed_mime_types) VALUES('expert-materials','expert-materials',false,10485760,ARRAY['application/pdf']);
CREATE POLICY "Upload own expert PDF" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='expert-materials' AND name ~ ('^'||auth.uid()::text||'/[0-9a-f-]{36}\.pdf$'));
CREATE POLICY "Read own or deliberately published expert PDF" ON storage.objects FOR SELECT TO authenticated USING(
 bucket_id='expert-materials' AND ((storage.foldername(name))[1]=auth.uid()::text OR EXISTS(SELECT 1 FROM public.feature_records r WHERE r.kind='expert_resource' AND r.payload->>'storage_path'=name AND r.visibility='public' AND EXISTS(SELECT 1 FROM public.feature_records p WHERE p.id=(r.payload->>'expert_id')::uuid AND p.kind='expert' AND p.owner_id=r.owner_id AND p.visibility='public')))
);
CREATE POLICY "Remove own expert PDF" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='expert-materials' AND (storage.foldername(name))[1]=auth.uid()::text);
REVOKE ALL ON FUNCTION public.kinra_safe_external_url(text),public.kinra_guard_expert_resource(),public.kinra_expert_published(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.kinra_safe_external_url(text),public.kinra_expert_published(uuid,uuid) TO authenticated,service_role;
